    uint8_t n;
    for (n = 2; n != 16; n++) {
        if (x & (1 << n)) {
            r = r + (r << n);
            x -= mbin_log_32_table[n];
        }
    }
    r *= 1 - (x & 0xFFFF0000);
    return r;
